<!DOCTYPE html><html lang="<?php echo html_escape($lang); ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0E6F5B"><title><?php echo html_escape(_l('smartsource_submission_thank_you')); ?></title><link rel="stylesheet" href="<?php echo base_url('assets/plugins/bootstrap/css/bootstrap.min.css'); ?>"><style>
*{box-sizing:border-box}body{--ss-primary:<?php echo html_escape($primary_color); ?>;--ss-secondary:<?php echo html_escape($secondary_color); ?>;--ss-success:<?php echo html_escape($success_color); ?>;background:#eef3f1;font-family:Arial,sans-serif;color:#1f2937;padding:24px;margin:0}.portal-wrap{max-width:900px;margin:0 auto}.success-card{background:#fff;border-radius:18px;box-shadow:0 18px 45px rgba(0,0,0,.16);padding:38px;text-align:center;border-top:6px solid var(--ss-success)}.logo-stage{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:300px;min-height:104px}.success-logo{position:relative;z-index:2;max-height:82px;max-width:280px;object-fit:contain;background:#fff;border-radius:14px;padding:8px;box-shadow:0 8px 24px rgba(0,0,0,.14)}.logo-particle{position:absolute;z-index:3;width:7px;height:7px;background:rgba(255,255,255,.96);border-radius:2px;pointer-events:none;animation:logoBreak 2.8s ease-in-out infinite;opacity:0}.logo-particle:nth-child(3n){background:rgba(53,152,219,.9)}.logo-particle:nth-child(4n){background:rgba(242,140,40,.9)}@keyframes logoBreak{0%,15%{transform:translate(0,0) scale(1);opacity:0}28%{opacity:.95}65%{transform:translate(var(--dx),var(--dy)) rotate(var(--rot)) scale(.45);opacity:.15}100%{transform:translate(0,0) scale(.2);opacity:0}}@media(prefers-reduced-motion:reduce){.logo-particle{display:none}}.success-icon{width:86px;height:86px;border-radius:50%;background:var(--ss-success);color:#fff;display:flex;align-items:center;justify-content:center;margin:10px auto 18px;font-size:42px;font-weight:900;box-shadow:0 12px 28px rgba(22,145,121,.30)}h1{font-weight:800;color:#111827;margin:0 0 12px}p{font-size:16px;line-height:1.7;color:#4b5563}.actions{display:grid;grid-template-columns:repeat(2,minmax(220px,1fr));justify-content:center;gap:12px;max-width:620px;margin:0 auto}.btn-smart,.btn-home,.btn-login{color:#fff;border:0;font-weight:700;border-radius:9px;padding:11px 18px}.btn-smart{background:var(--ss-success)}.btn-home{background:var(--ss-primary)}.btn-login{background:var(--ss-secondary)}.portal-footer{margin-top:22px;background:#fff;border-radius:14px;padding:20px;text-align:center;box-shadow:0 10px 28px rgba(0,0,0,.10);color:#64748b}.portal-footer a{color:#3598DB;font-weight:700;margin:0 6px}.language-box{text-align:right;margin-bottom:12px}.paper-burst{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:9999}.paper-burst i{position:absolute;top:-30px;width:11px;height:18px;border-radius:2px;animation:paperFall 3.4s linear forwards}.paper-burst i:nth-child(3n){background:#3598DB}.paper-burst i:nth-child(3n+1){background:#F28C28}.paper-burst i:nth-child(3n+2){background:#169179}@keyframes paperFall{to{transform:translate(var(--drift),110vh) rotate(900deg);opacity:.12}}@media(max-width:767px){body{padding:10px}.success-card{padding:22px}.language-box{text-align:center}.logo-stage{min-width:0;width:100%}.success-logo{max-width:225px}.actions{display:grid;grid-template-columns:1fr}.actions .btn{width:100%;min-height:44px}h1{font-size:26px}}
</style></head><body><div class="paper-burst" id="paperBurst" style="<?php echo $success_animation==='none'?'display:none':''; ?>"></div><div class="portal-wrap"><div class="language-box"><a href="?lang=en" class="btn btn-xs <?php echo $lang==='en'?'btn-primary':'btn-default'; ?>">English</a> <a href="?lang=es" class="btn btn-xs <?php echo $lang==='es'?'btn-primary':'btn-default'; ?>">Español</a></div><div class="success-card"><div class="logo-stage" id="smartLogoStage"><img src="<?php echo html_escape($logo_url); ?>" class="success-logo" alt="Smart Choice Contractors USA"></div><div class="success-icon">✓</div><h1><?php echo _l('smartsource_submission_thank_you'); ?></h1><div class="alert alert-success" style="border-radius:12px;font-weight:800;font-size:16px;margin:14px auto;max-width:620px">✓ <?php echo _l('smartsource_submission_received'); ?></div><p><?php echo _l('smartsource_submission_message'); ?></p><p><?php echo _l('smartsource_submission_next'); ?></p><hr><div class="actions"><a href="<?php echo html_escape($home_url); ?>" target="_blank" rel="noopener" class="btn btn-home"><?php echo _l('smartsource_visit_website'); ?></a><a href="<?php echo html_escape($login_url); ?>" class="btn btn-login"><?php echo _l('smartsource_login_account'); ?></a></div></div><footer class="portal-footer"><strong><?php echo html_escape(get_option('companyname')); ?></strong><br><?php echo _l('smartsource_portal_footer_text'); ?><div style="margin-top:8px"><a href="<?php echo html_escape($home_url); ?>" target="_blank" rel="noopener"><?php echo _l('smartsource_visit_website'); ?></a><a href="<?php echo html_escape($login_url); ?>"><?php echo _l('smartsource_login_account'); ?></a></div><div style="margin-top:8px">&copy; <?php echo date('Y'); ?> <?php echo html_escape(get_option('companyname')); ?></div></footer></div><script>(function(){var stage=document.getElementById('smartLogoStage');if(stage&&<?php echo $logo_animation==='none'?'false':'true'; ?>&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){for(var i=0;i<24;i++){var p=document.createElement('i');p.className='logo-particle';p.style.left=(18+Math.random()*64)+'%';p.style.top=(20+Math.random()*58)+'%';p.style.setProperty('--dx',((Math.random()-.5)*150)+'px');p.style.setProperty('--dy',((Math.random()-.5)*100)+'px');p.style.setProperty('--rot',((Math.random()*360)-180)+'deg');p.style.animationDelay=(Math.random()*2.8)+'s';stage.appendChild(p);}}var burst=document.getElementById('paperBurst');if(burst&&<?php echo $success_animation==='none'?'false':'true'; ?>&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){for(var j=0;j<70;j++){var c=document.createElement('i');c.style.left=(Math.random()*100)+'vw';c.style.animationDelay=(Math.random()*1.1)+'s';c.style.animationDuration=(2.5+Math.random()*2)+'s';c.style.setProperty('--drift',((Math.random()-.5)*260)+'px');burst.appendChild(c);}}setTimeout(function(){if(burst){burst.remove();}},6000);})();</script></body></html>
